// ---------------------------------------------------------------- ratio hotspots (segment-level KPIs)
let ratioSeq = 0
for (const def of RATIO_METRICS) {
  for (const dim of def.dims) {
    const p = `ratio.${def.id}.${dim}`
    const code = `RAT-${String(++ratioSeq).padStart(3, '0')}`
    const dimP: Param = { t: lower(ROLE_META[dim].label) }
    const metricP: Param = { t: def.label }
    const domain: Domain | 'generic' = ['defect_rate', 'downtime_avg', 'output_ach'].includes(def.id) ? 'manufacturing' : ['roas', 'cpl', 'ctr'].includes(def.id) ? 'marketing' : ['absence', 'salary_avg', 'performance_avg'].includes(def.id) ? 'hr' : ['response_avg', 'satisfaction_avg'].includes(def.id) ? 'customer_service' : def.id === 'duration_avg' ? 'operations' : def.id === 'budget_util' ? 'finance' : def.id === 'target_ach' ? 'sales' : 'retail'
    const recs: Record<string, string[]> = {
      defect_rate: ['quality_rootcause'], downtime_avg: ['maintenance'], output_ach: ['capacity_plan'], roas: ['optimize_channels'], cpl: ['optimize_channels', 'creative_test'], ctr: ['creative_test'],
      margin: ['decompose_margin', 'review_pricing'], absence: ['attendance_review'], salary_avg: ['payroll_review'], performance_avg: ['performance_program'], return_rate: ['reduce_returns'],
      response_avg: ['service_capacity'], duration_avg: ['process_review'], satisfaction_avg: ['service_quality'], target_ach: ['close_target_gap'], budget_util: ['budget_control'],
    }
    const badIsHigh = def.better === 'low'
    // the "bad" extreme: highest for bad-high metrics, lowest for good-high metrics
    if (badIsHigh) {
      add({ id: code, domain, requires: [`${p}.max`, `${p}.avg`, `${p}.n`], condition: `highest ${def.id} by ${dim} >= 1.5 × average`, severity: 'watch', template: 'ratio_hotspot', recommendations: recs[def.id] ?? ['review_segment'], metric: def.id, when: (f) => f[`${p}.avg`] > 0 && f[`${p}.max`] >= 1.5 * f[`${p}.avg`] && f[`${p}.n`] >= 2, params: (f, l) => ({ dim: dimP, top: l[`${p}.max`] ?? '', metric: metricP, value: { v: f[`${p}.max`], f: def.format }, avg: { v: f[`${p}.avg`], f: def.format } }), magnitude: (f) => f[`${p}.max`] / f[`${p}.avg`] / 4, focus: 'dashboard' })
    } else {
      add({ id: code, domain, requires: [`${p}.min`, `${p}.avg`, `${p}.n`], condition: `lowest ${def.id} by ${dim} <= 0.7 × average`, severity: 'watch', template: 'ratio_low', recommendations: recs[def.id] ?? ['review_segment'], metric: def.id, when: (f) => f[`${p}.avg`] > 0 && f[`${p}.min`] <= 0.7 * f[`${p}.avg`] && f[`${p}.n`] >= 2, params: (f, l) => ({ dim: dimP, top: l[`${p}.min`] ?? '', metric: metricP, value: { v: f[`${p}.min`], f: def.format }, avg: { v: f[`${p}.avg`], f: def.format } }), magnitude: (f) => (1 - f[`${p}.min`] / f[`${p}.avg`]) / 2, focus: 'dashboard' })
      add({ id: `${code}B`, domain, requires: [`${p}.max`, `${p}.avg`, `${p}.n`], condition: `highest ${def.id} by ${dim} >= 1.4 × average`, severity: 'opportunity', template: 'ratio_best', recommendations: ['scale_winner'], metric: def.id, when: (f) => f[`${p}.avg`] > 0 && f[`${p}.max`] >= 1.4 * f[`${p}.avg`] && f[`${p}.n`] >= 3, params: (f, l) => ({ dim: dimP, top: l[`${p}.max`] ?? '', metric: metricP, value: { v: f[`${p}.max`], f: def.format }, avg: { v: f[`${p}.avg`], f: def.format } }), magnitude: (f) => f[`${p}.max`] / f[`${p}.avg`] / 5 })
    }
  }
}

