export const RULE_LIBRARY: readonly RuleDef[] = RULES

export function ruleCountsByDomain(): Record<string, number> {
  const out: Record<string, number> = {}
  for (const r of RULES) out[r.domain] = (out[r.domain] ?? 0) + 1
  return out
}
